// Headless check of Prototype 2, network style "Mycelium" (2026-11-14), the
// port of tools/mycelium_lookdev/index.html. Compiles the real
// SuccessionModel.cpp, MycorrhizaField(.cpp, Layers.cpp) and MyceliumSim.cpp
// (no openFrameworks) on a 519 x 295 grid at 1.9 mm per cell, 40 steps/s.
// The GPU passes of MycorrhizaRendererMycelium.cpp (shaders generated by
// gen_mycelium_shaders.py) are copied here in C++ with the same formulas,
// resolutions and noise bytes: curl -> LIC -> fibre advection -> threads ->
// shade -> bright -> blur (two levels) -> tone map. The image is the
// grid-space image (2 px per cell) the renderer maps onto the sand.
//
//   stable: still sand, +-1 mm per-cell noise every frame for 60 s: touches,
//           new light, and the mean absolute frame-to-frame difference of the
//           rendered image (0..255), at the default Sand visibility (0) and
//           at the page's 0.12.
//   ident:  SuccessionModel bit-identical with the module on or off (2,000
//           steps, with sweeps).
//   bench:  one module step at the default settings, by part.
//   story:  synthetic sand (as the page's sandData), 30 s untouched, then
//           60 s of demo strokes round three hubs (as the page's demoStep),
//           then 90 s without touch; GIF frames.
//
// Usage: ./mycelium_harness <outdir> [repoRoot] [stable|ident|bench|story ...]
#include "../../src/Games/SuccessionModel.h"
#include "../../src/Prototypes/Mycorrhiza/MycorrhizaField.h"
#include "../dewitz_harness/png.h"
#include <algorithm>
#include <array>
#include <deque>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <random>
#include <sstream>
#include <string>
#include <vector>

typedef SuccessionModel SM;
typedef MycorrhizaField MF;
typedef MyceliumSim MS;
static std::string OUT, ROOT = "../..";
static const float DT = 1.0f / 40.0f;
static const float MM = 1.9f;
static const float TABLE_MM = -15.0f;
static const int GW = 519, GH = 295;

// ------------------------------------------------------------ display settings (renderer defaults)
static float FIBRE_LEN = 50, FIBRE = 1.2f, SWIRL_SCALE = 6, STROKE_W = 0.9f, STREAK_FLOW = 25, TEX_SLOPE = 0, CARRY = 0.6f, RELAX = 0.3f;
static float MATURE = 4, EDGE_COOL = 0.6f, EXPOSURE = 1.4f, CONTRAST = 3.2f, GAMMA_ = 1.3f, BASE = 0.14f, LIGHT_COL = 0, SHEEN = 0.4f;
static float RELIEF = 0.6f, FIB_RELIEF = 2, SHINE = 30, RIM = 0.3f, BLOOM = 0.5f, BLOOM_THRESH = 0.6f, SAND = 0.0f;
static float THREAD_BRIGHT = 0.45f, PULSE_GAIN = 0.8f, PULSE_SPEED = 0.6f, PULSE_LEN = 45, PULSE_SHARP = 3, MIN_THREAD_PX = 1.5f;
static float BRUSH = 34, PILE = 0.6f;          // page: Hand size, Sand pushed ahead
// The page's Dig rate (10 mm/s) digs ~4 mm per pass at 100 mm/s, at the edge of the real touch
// threshold (the page lights from the pointer, not from the sand); the simulated sweeps dig harder.
static const float HARNESS_CARVE = 25.0f;
static const float HARNESS_SPEED = 100.0f;     // mm/s (the page's demo strokes move 160 px/s)
struct V3 { float r, g, b; };
static V3 hexc(unsigned v) { return { ((v >> 16) & 255) / 255.f, ((v >> 8) & 255) / 255.f, (v & 255) / 255.f }; }
static V3 C0 = hexc(0x3FD8FF), C1 = hexc(0xCFEFFF), C2 = hexc(0xFFB347), C3 = hexc(0xF07A2A), TROUGH = hexc(0x0A2A6E), THREAD_COL = hexc(0xCFF4FF);

// ------------------------------------------------------------ images and sampling (GL_LINEAR, clamp to edge; rectangle textures)
struct Img {
	int w = 0, h = 0, ch = 4;
	std::vector<float> d;
	void alloc(int W, int H, int C = 4) { w = W; h = H; ch = C; d.assign((size_t)W * H * C, 0.0f); }
	float * at(int x, int y) { return &d[((size_t)y * w + x) * ch]; }
	const float * at(int x, int y) const { return &d[((size_t)y * w + x) * ch]; }
};
static void sample(const Img & t, float x, float y, float * out)
{
	x -= 0.5f; y -= 0.5f;
	int x0 = (int)std::floor(x), y0 = (int)std::floor(y);
	const float tx = x - x0, ty = y - y0;
	auto c = [&](int xi, int yi) { xi = std::max(0, std::min(t.w - 1, xi)); yi = std::max(0, std::min(t.h - 1, yi)); return t.at(xi, yi); };
	const float * a = c(x0, y0), * b = c(x0 + 1, y0), * cc = c(x0, y0 + 1), * d = c(x0 + 1, y0 + 1);
	for (int k = 0; k < t.ch; k++) out[k] = (a[k] * (1 - tx) + b[k] * tx) * (1 - ty) + (cc[k] * (1 - tx) + d[k] * tx) * ty;
}
static float sample1(const Img & t, float x, float y, int k = 0) { float o[4]; sample(t, x, y, o); return o[k]; }
// The renderer's noise texture (same generator), sampler2D with repeat.
static std::vector<float> NOISE;
static void makeNoise()
{
	NOISE.resize(256 * 256);
	uint32_t s = 12345u;
	for (int i = 0; i < 256 * 256; i++) { s = s * 1664525u + 1013904223u; NOISE[i] = (float)(unsigned char)(s >> 24) / 255.0f; }
}
static float noiseAt(float u, float v) // normalised coordinates
{
	float x = u * 256 - 0.5f, y = v * 256 - 0.5f;
	int x0 = (int)std::floor(x), y0 = (int)std::floor(y);
	const float tx = x - x0, ty = y - y0;
	auto c = [&](int xi, int yi) { xi &= 255; yi &= 255; return NOISE[(size_t)yi * 256 + xi]; };
	return (c(x0, y0) * (1 - tx) + c(x0 + 1, y0) * tx) * (1 - ty) + (c(x0, y0 + 1) * (1 - tx) + c(x0 + 1, y0 + 1) * tx) * ty;
}
static float fractf(float x) { return x - std::floor(x); }
static float hash12(float x, float y)
{
	float a = fractf(x * 0.1031f), b = fractf(y * 0.1031f), c = fractf(x * 0.1031f);
	float d = a * (b + 33.33f) + b * (c + 33.33f) + c * (a + 33.33f);
	a += d; b += d; c += d;
	return fractf((a + b) * c);
}
static float vnoise(float x, float y)
{
	float ix = std::floor(x), iy = std::floor(y), fx = x - ix, fy = y - iy;
	float ux = fx * fx * (3 - 2 * fx), uy = fy * fy * (3 - 2 * fy);
	float a = hash12(ix, iy), b = hash12(ix + 1, iy), c = hash12(ix, iy + 1), d = hash12(ix + 1, iy + 1);
	float ab = a + (b - a) * ux, cd = c + (d - c) * ux;
	return ab + (cd - ab) * uy;
}
static float smoothstepf(float a, float b, float x) { float t = std::min(1.0f, std::max(0.0f, (x - a) / (b - a))); return t * t * (3 - 2 * t); }

// ------------------------------------------------------------ the renderer's passes in C++
struct Look {
	int FP = 2, FW = 0, FH = 0;
	Img mask, aux, liq, swirl, base, fib, fibN, thr, shade, b1a, b1b, b2a, b2b, fin;
	bool fibValid = false;
	void alloc() {
		FP = MS::FIB_PX; FW = GW * FP; FH = GH * FP;
		swirl.alloc(FW / 4, FH / 4); base.alloc(FW, FH); fib.alloc(FW, FH); fibN.alloc(FW, FH); thr.alloc(FW, FH);
		shade.alloc(FW, FH); b1a.alloc(FW / 2, FH / 2); b1b.alloc(FW / 2, FH / 2); b2a.alloc(FW / 8, FH / 8); b2b.alloc(FW / 8, FH / 8);
		fin.alloc(FW, FH);
	}
	void upload(const MS & s) {
		mask.alloc(s.getCols(), s.getRows()); aux.alloc(s.getCols(), s.getRows()); liq.alloc(s.getLiquidCols(), s.getLiquidRows());
		for (int i = 0; i < GW * GH; i++) {
			float * m = &mask.d[4 * i]; m[0] = s.lit()[i]; m[1] = s.age()[i]; m[2] = s.dirX()[i]; m[3] = s.dirY()[i];
			float * a = &aux.d[4 * i]; a[0] = s.modelWarm()[i]; a[1] = s.smoothSand()[i]; a[3] = 1;
		}
		for (int l = 0; l < liq.w * liq.h; l++) { float * q = &liq.d[4 * l]; q[0] = s.liquidDepth()[l]; q[1] = s.liquidVelX()[l]; q[2] = s.liquidVelY()[l]; q[3] = 1; }
	}
	// myc_curl.frag
	void curl() {
		const float W = (float)swirl.w, H = (float)swirl.h;
		for (int y = 0; y < swirl.h; y++)
			for (int x = 0; x < swirl.w; x++) {
				const float pxx = x + 0.5f, pyy = y + 0.5f;
				const float u = pxx / W, v = pyy / H;
				const float cpx = pxx / H * SWIRL_SCALE, cpy = pyy / H * SWIRL_SCALE, h = 0.01f;
				float cx = (vnoise(cpx, cpy + h) - vnoise(cpx, cpy - h)) / (2 * h), cy = -(vnoise(cpx + h, cpy) - vnoise(cpx - h, cpy)) / (2 * h);
				cx += 0.5f * (vnoise(cpx * 2.7f + 3.0f, cpy * 2.7f) - 0.5f); cy += 0.5f * (vnoise(cpx * 2.7f, cpy * 2.7f + 5.0f) - 0.5f);
				const float tx = u * mask.w, ty = v * mask.h;
				const float gx = 0.5f * (sample1(aux, tx + 1, ty, 1) - sample1(aux, tx - 1, ty, 1));
				const float gy = 0.5f * (sample1(aux, tx, ty + 1, 1) - sample1(aux, tx, ty - 1, 1));
				const float sl = std::hypot(gx, gy), cl = std::hypot(cx, cy) + 1e-4f;
				const float sw = TEX_SLOPE * smoothstepf(0.05f, 0.6f, sl);
				float dx = cx / cl + (-gx / (sl + 1e-4f) - cx / cl) * sw, dy = cy / cl + (-gy / (sl + 1e-4f) - cy / cl) * sw;
				float m[4]; sample(mask, tx, ty, m);
				const float ml = std::hypot(m[2], m[3]);
				if (ml > 1e-3f) { const float k = STROKE_W * smoothstepf(0.1f, 0.5f, m[0]); dx += (m[2] / ml - dx) * k; dy += (m[3] / ml - dy) * k; }
				float * o = swirl.at(x, y); o[0] = dx; o[1] = dy; o[2] = 0; o[3] = 1;
			}
	}
	// myc_lic.frag
	void lic() {
		const float ds = std::max(0.7f * FIBRE, FIBRE_LEN / 48.0f);
		auto nz = [&](float px, float py) { return noiseAt(px / (256.0f * FIBRE), py / (256.0f * FIBRE)); };
		for (int y = 0; y < FH; y++)
			for (int x = 0; x < FW; x++) {
				const float p0x = x + 0.5f, p0y = y + 0.5f;
				float acc = 0.5f * nz(p0x, p0y), ws = 0.5f;
				for (int dir = -1; dir <= 1; dir += 2) {
					float px = p0x, py = p0y;
					for (int i = 0; i < 48; i++) {
						if ((i + 1) * ds > FIBRE_LEN) break;
						float vv[4]; sample(swirl, px / FW * swirl.w, py / FH * swirl.h, vv);
						const float l = std::hypot(vv[0], vv[1]);
						if (l < 1e-4f) break;
						px += dir * vv[0] / l * ds; py += dir * vv[1] / l * ds;
						const float w = 1.0f - (i + 1) * ds / FIBRE_LEN;
						acc += w * nz(px, py); ws += w;
					}
				}
				base.at(x, y)[0] = acc / ws;
			}
	}
	// myc_fib.frag
	void advect(float dt) {
		const bool reset = !fibValid;
		const Img & src = reset ? base : fib;
		for (int y = 0; y < FH; y++)
			for (int x = 0; x < FW; x++) {
				const float u = (x + 0.5f) / FW, v = (y + 0.5f) / FH;
				float q[4]; sample(liq, u * liq.w, v * liq.h, q);
				float vx = CARRY * q[1] / liq.w, vy = CARRY * q[2] / liq.h;
				float m[4]; sample(mask, u * mask.w, v * mask.h, m);
				const float ml = std::hypot(m[2], m[3]);
				if (ml > 1e-3f) { vx += STREAK_FLOW * m[0] * (m[2] / ml) / FW; vy += STREAK_FLOW * m[0] * (m[3] / ml) / FH; }
				const float d = reset ? 0.0f : dt;
				const float f = sample1(src, (u - d * vx) * FW, (v - d * vy) * FH);
				const float b = base.at(x, y)[0];
				fibN.at(x, y)[0] = f + (b - f) * (1.0f - std::exp(-d * RELAX));
			}
		std::swap(fib.d, fibN.d);
		fibValid = true;
	}
	// myc_thread.vert/.frag: additive into thr (R thread, G pulse)
	void threads(const MS & s) {
		std::fill(thr.d.begin(), thr.d.end(), 0.0f);
		if (!MS::THREADS_ON) return;
		const float now = (float)s.getTime(), fade = s.fadeRate();
		for (const MS::Segment & sg : s.segments()) {
			if (sg.width <= 0) continue;
			const float w = std::max(sg.width, MIN_THREAD_PX); // harness image px = projector px
			float dx = sg.x1 - sg.x0, dy = sg.y1 - sg.y0;
			const float len = std::hypot(dx, dy);
			if (len > 1e-5f) { dx /= len; dy /= len; } else { dx = 1; dy = 0; }
			const float ax = sg.x0 - dx * w * 0.5f, ay = sg.y0 - dy * w * 0.5f, L = len + w;
			const float fd = std::exp(-std::max(now - sg.birth, 0.0f) * fade);
			const int x0 = std::max(0, (int)std::floor(std::min(sg.x0, sg.x1) - 2 * w)), x1 = std::min(FW - 1, (int)std::ceil(std::max(sg.x0, sg.x1) + 2 * w));
			const int y0 = std::max(0, (int)std::floor(std::min(sg.y0, sg.y1) - 2 * w)), y1 = std::min(FH - 1, (int)std::ceil(std::max(sg.y0, sg.y1) + 2 * w));
			for (int y = y0; y <= y1; y++)
				for (int x = x0; x <= x1; x++) {
					const float rx = x + 0.5f - ax, ry = y + 0.5f - ay;
					const float t = rx * dx + ry * dy, a = (-rx * dy + ry * dx); // along from the extended start; across (left +)
					if (t < 0 || t > L || std::fabs(a) > 1.5f * w) continue;
					const float side = a / w;
					const float sv = sg.s0 + (sg.s1 - sg.s0) * (t / L);
					const float core = std::exp(-side * side * 2.5f);
					const float pulse = std::pow(0.5f + 0.5f * std::cos(6.2831853f * (sv / PULSE_LEN - now * PULSE_SPEED + sg.phase)), PULSE_SHARP);
					float * o = thr.at(x, y); o[0] += core * fd; o[1] += core * fd * pulse;
				}
		}
	}
	static V3 mixv(V3 a, V3 b, float t) { return { a.r + (b.r - a.r) * t, a.g + (b.g - a.g) * t, a.b + (b.b - a.b) * t }; }
	static V3 ramp(float m) {
		m = std::min(1.0f, std::max(0.0f, m)) * 3.0f;
		if (m < 1) return mixv(C0, C1, m);
		if (m < 2) return mixv(C1, C2, m - 1);
		return mixv(C2, C3, m - 2);
	}
	// myc_shade.frag
	void shadePass() {
		auto surf = [&](float u, float v) { return sample1(aux, u * aux.w, v * aux.h, 1) + sample1(liq, u * liq.w, v * liq.h, 0); };
		float Ld[3] = { -0.5f, -0.55f, 0.65f }; { float l = std::sqrt(Ld[0] * Ld[0] + Ld[1] * Ld[1] + Ld[2] * Ld[2]); for (float & v : Ld) v /= l; }
		float Hv[3] = { Ld[0], Ld[1], Ld[2] + 1 }; { float l = std::sqrt(Hv[0] * Hv[0] + Hv[1] * Hv[1] + Hv[2] * Hv[2]); for (float & v : Hv) v /= l; }
		float Ls[3] = { -0.5f, -0.6f, 0.65f }; { float l = std::sqrt(Ls[0] * Ls[0] + Ls[1] * Ls[1] + Ls[2] * Ls[2]); for (float & v : Ls) v /= l; }
		for (int y = 0; y < FH; y++)
			for (int x = 0; x < FW; x++) {
				const float pxx = x + 0.5f, pyy = y + 0.5f, u = pxx / FW, v = pyy / FH, mtx = u * mask.w, mty = v * mask.h;
				float mk[4]; sample(mask, mtx, mty, mk);
				const float P = smoothstepf(0.05f, 0.6f, mk[0]);
				const float ex = sample1(mask, mtx + 1, mty) - sample1(mask, mtx - 1, mty), ey = sample1(mask, mtx, mty + 1) - sample1(mask, mtx, mty - 1);
				const float edge = smoothstepf(0.02f, 0.2f, std::hypot(ex, ey));
				const float fraw = sample1(fib, pxx, pyy);
				const float fibv = std::pow(std::min(1.0f, std::max(0.0f, (fraw - 0.5f) * CONTRAST + 0.5f)), GAMMA_);
				const float fgx = sample1(fib, pxx + 1, pyy) - sample1(fib, pxx - 1, pyy), fgy = sample1(fib, pxx, pyy + 1) - sample1(fib, pxx, pyy - 1);
				const float warm = MS::WARM_FROM_MODEL ? sample1(aux, mtx, mty, 0) : 1.0f - std::exp(-mk[1] / std::max(MATURE, 0.1f));
				const float m = warm * (1.0f - EDGE_COOL * edge);
				const float elx = 1.0f / liq.w, ely = 1.0f / liq.h;
				const float gx = surf(u + elx, v) - surf(u - elx, v), gy = surf(u, v + ely) - surf(u, v - ely);
				float n[3] = { -gx * RELIEF - fgx * FIB_RELIEF * CONTRAST, -gy * RELIEF - fgy * FIB_RELIEF * CONTRAST, 1.0f };
				{ float l = std::sqrt(n[0] * n[0] + n[1] * n[1] + n[2] * n[2]); for (float & q : n) q /= l; }
				const float diff = std::max(n[0] * Ld[0] + n[1] * Ld[1] + n[2] * Ld[2], 0.0f);
				const float spec = std::pow(std::max(n[0] * Hv[0] + n[1] * Hv[1] + n[2] * Hv[2], 0.0f), SHINE) * SHEEN;
				const float lightKey = std::min(1.0f, std::max(0.0f, 0.85f * diff + 0.35f * fibv - 0.2f));
				const float key = m * (0.55f + 0.45f * fibv) + (lightKey - m * (0.55f + 0.45f * fibv)) * LIGHT_COL;
				const V3 rc = mixv(TROUGH, ramp(key), smoothstepf(0.0f, 0.6f, fibv));
				const float k = (BASE + fibv) * (0.75f + 0.35f * diff) * P * EXPOSURE;
				const V3 sc = mixv(C1, C2, LIGHT_COL);
				float col[3] = { rc.r * k + spec * sc.r * P + RIM * edge * C1.r * P, rc.g * k + spec * sc.g * P + RIM * edge * C1.g * P,
					rc.b * k + spec * sc.b * P + RIM * edge * C1.b * P };
				float th[4]; sample(thr, pxx, pyy, th);
				const float T = std::min(th[0], 1.0f), Pu = std::min(th[1], 1.0f);
				const V3 pr = ramp(0.55f + 0.45f * Pu);
				const float tb = MS::THREADS_ON ? THREAD_BRIGHT : 0.0f, pg = MS::THREADS_ON ? PULSE_GAIN : 0.0f;
				col[0] += (THREAD_COL.r * tb + pr.r * Pu * pg) * T * EXPOSURE;
				col[1] += (THREAD_COL.g * tb + pr.g * Pu * pg) * T * EXPOSURE;
				col[2] += (THREAD_COL.b * tb + pr.b * Pu * pg) * T * EXPOSURE;
				const float tgx = sample1(aux, mtx + 1, mty, 1) - sample1(aux, mtx - 1, mty, 1), tgy = sample1(aux, mtx, mty + 1, 1) - sample1(aux, mtx, mty - 1, 1);
				float sn[3] = { -tgx * 0.35f, -tgy * 0.35f, 1.0f }; { float l = std::sqrt(sn[0] * sn[0] + sn[1] * sn[1] + sn[2] * sn[2]); for (float & q : sn) q /= l; }
				const float sh = std::max(0.0f, sn[0] * Ls[0] + sn[1] * Ls[1] + sn[2] * Ls[2]);
				const float sd = (0.35f + 0.65f * sh) * SAND * (1.0f - P);
				col[0] += 0.36f * sd; col[1] += 0.32f * sd; col[2] += 0.27f * sd;
				float * o = shade.at(x, y); o[0] = col[0]; o[1] = col[1]; o[2] = col[2]; o[3] = 1;
			}
	}
	static void bright(const Img & src, Img & dst) {
		for (int y = 0; y < dst.h; y++)
			for (int x = 0; x < dst.w; x++) {
				float c[4]; sample(src, (x + 0.5f) / dst.w * src.w, (y + 0.5f) / dst.h * src.h, c);
				const float br = std::max(c[0], std::max(c[1], c[2])), k = std::max(br - BLOOM_THRESH, 0.0f) / std::max(br, 1e-4f);
				float * o = dst.at(x, y); o[0] = c[0] * k; o[1] = c[1] * k; o[2] = c[2] * k; o[3] = 1;
			}
	}
	static void blur(const Img & src, Img & dst, float sx, float sy) {
		static const float O[2] = { 1.3846154f, 3.2307692f }, Wt[2] = { 0.3162162f, 0.0702703f };
		for (int y = 0; y < dst.h; y++)
			for (int x = 0; x < dst.w; x++) {
				const float u = (x + 0.5f) / dst.w, v = (y + 0.5f) / dst.h;
				float c[4], acc[3];
				sample(src, u * src.w, v * src.h, c);
				for (int k = 0; k < 3; k++) acc[k] = c[k] * 0.2270270f;
				for (int i = 0; i < 2; i++)
					for (int sgn = -1; sgn <= 1; sgn += 2) {
						sample(src, (u + sgn * sx * O[i]) * src.w, (v + sgn * sy * O[i]) * src.h, c);
						for (int k = 0; k < 3; k++) acc[k] += c[k] * Wt[i];
					}
				float * o = dst.at(x, y); o[0] = acc[0]; o[1] = acc[1]; o[2] = acc[2]; o[3] = 1;
			}
	}
	std::vector<unsigned char> render(const MS & s) {
		threads(s);
		shadePass();
		bright(shade, b1a);
		const float W2 = FW / 2.0f, H2 = FH / 2.0f, W8 = FW / 8.0f, H8 = FH / 8.0f;
		for (int i = 0; i < 2; i++) { blur(b1a, b1b, 2.0f / W2, 0); blur(b1b, b1a, 0, 2.0f / H2); }
		blur(b1a, b2b, 1.0f / W8, 0); blur(b2b, b2a, 0, 1.0f / H8);
		for (int i = 0; i < 2; i++) { blur(b2a, b2b, 2.0f / W8, 0); blur(b2b, b2a, 0, 2.0f / H8); }
		std::vector<unsigned char> img((size_t)FW * FH * 3);
		for (int y = 0; y < FH; y++)
			for (int x = 0; x < FW; x++) {
				const float u = (x + 0.5f) / FW, v = (y + 0.5f) / FH;
				float a[4], b[4]; sample(b1a, u * b1a.w, v * b1a.h, a); sample(b2a, u * b2a.w, v * b2a.h, b);
				const float * sh = shade.at(x, y);
				for (int k = 0; k < 3; k++) {
					float c = sh[k] + BLOOM * (a[k] + 0.6f * b[k]);
					c = std::pow(1.0f - std::exp(-c * 1.35f), 0.95f);
					img[((size_t)y * FW + x) * 3 + k] = (unsigned char)std::lround(std::min(1.0f, std::max(0.0f, c)) * 255.0f);
				}
			}
		return img;
	}
	void step(MS & s, float dt) { // per simulation step, as the renderer per frame (render() separately)
		upload(s);
		if (s.baseDirty() || !fibValid) { curl(); lic(); s.baseRebuilt(); }
		advect(dt);
	}
};

// ------------------------------------------------------------ world: the page's synthetic sand and simulated hand
struct World {
	std::vector<float> sand, elev, above;
	std::vector<unsigned char> water;
	std::mt19937 rng{ 3 };
	float noiseMM = 1.0f;
	World() : sand(GW * GH), elev(GW * GH), above(GW * GH), water(GW * GH, 0) {}
	static float hashJ(float x, float y) { float s = std::sin(x * 127.1f + y * 311.7f) * 43758.5453f; return s - std::floor(s); }
	static float vnoiseJ(float x, float y) {
		const float ix = std::floor(x), iy = std::floor(y), fx = x - ix, fy = y - iy;
		const float ux = fx * fx * (3 - 2 * fx), uy = fy * fy * (3 - 2 * fy);
		const float a = hashJ(ix, iy), b = hashJ(ix + 1, iy), c = hashJ(ix, iy + 1), d = hashJ(ix + 1, iy + 1);
		return (a + (b - a) * ux) + ((c + (d - c) * ux) - (a + (b - a) * ux)) * uy;
	}
	void pageSand() { // page sandData(), on this grid (u, v in 0..1; v down here, as the page's canvas rows)
		const float mounds[4][4] = { { 0.26f, 0.62f, 0.13f, 48 }, { 0.70f, 0.34f, 0.16f, 58 }, { 0.82f, 0.78f, 0.10f, 30 }, { 0.50f, 0.18f, 0.08f, -18 } };
		for (int j = 0; j < GH; j++) for (int i = 0; i < GW; i++) {
			const float u = (i + 0.5f) / GW, v = (j + 0.5f) / GH;
			float h = 9;
			for (auto & m : mounds) { const float dx = (u - m[0]) * 1.6f, dy = v - m[1]; h += m[3] * std::exp(-(dx * dx + dy * dy) / (2 * m[2] * m[2])); }
			h += 14 * std::exp(-std::pow((u - 0.47f - 0.05f * std::sin(v * 9)) / 0.035f, 2.0f)) * (v > 0.45f ? 1.0f : 0.0f);
			h += 6 * (vnoiseJ(u * 9, v * 6) - 0.5f) + 3 * (vnoiseJ(u * 23, v * 15) - 0.5f);
			sand[(size_t)j * GW + i] = h;
		}
	}
	// page handInput's carve and pile (Gaussian brush exp(-d^2 / r^2), r = Hand size), at cell resolution
	void carve(float cx, float cy, float depth, float radMM) {
		const float r = radMM / MM;
		for (int y = std::max(0, (int)(cy - 3 * r)); y <= std::min(GH - 1, (int)(cy + 3 * r)); y++)
			for (int x = std::max(0, (int)(cx - 3 * r)); x <= std::min(GW - 1, (int)(cx + 3 * r)); x++) {
				const float d2 = ((x - cx) * (x - cx) + (y - cy) * (y - cy)) / (r * r);
				sand[(size_t)y * GW + x] -= depth * std::exp(-d2);
			}
	}
	void sample(bool hand, float hx, float hy) {
		std::uniform_real_distribution<float> U(-noiseMM, noiseMM);
		for (int i = 0; i < GW * GH; i++) { elev[i] = sand[i] + U(rng); above[i] = sand[i] - TABLE_MM; }
		if (hand) { // the hand: depth samples under it rejected
			const float r = 0.5f * BRUSH / MM;
			for (int y = std::max(0, (int)(hy - r)); y <= std::min(GH - 1, (int)(hy + r)); y++)
				for (int x = std::max(0, (int)(hx - r)); x <= std::min(GW - 1, (int)(hx + r)); x++)
					if ((x - hx) * (x - hx) + (y - hy) * (y - hy) <= r * r) elev[(size_t)y * GW + x] = NAN;
		}
	}
	SM::Inputs smInputs() {
		SM::Inputs in;
		in.elevationMM = elev.data(); in.water = water.data(); in.heightAboveTableMM = above.data();
		in.cols = GW; in.rows = GH; in.mmPerCell = MM; in.dt = DT;
		in.temperature = 0.745f; in.restingTemperature = 0.745f; in.spreadRadiusMM = 40.0f;
		return in;
	}
	MF::Inputs mfInputs(const SM * m) const {
		MF::Inputs in;
		in.elevationMM = elev.data();
		const bool ok = m && m->getCols() == GW && m->getRows() == GH;
		for (int r = 0; r < 3; r++) in.cover[r] = ok ? m->cover(r) : nullptr;
		in.soil = ok ? m->soil() : nullptr;
		in.moisture = ok ? m->moisture() : nullptr;
		in.water = water.data();
		in.cols = GW; in.rows = GH; in.mmPerCell = MM; in.dt = DT;
		return in;
	}
};

// The page's demoStep: strokes round three hubs (page px ~ mm; hubs and speed scaled to this grid).
struct Demo {
	std::string phase = "pause";
	float left = 0.3f, x = 300, y = 300, a = 0, turn = 0;
	uint32_t seed = 11;
	float rnd() { seed = (uint32_t)(((uint64_t)seed * 16807ull) % 2147483647ull); return (seed - 1) / 2147483646.0f; }
	bool step(float dt, float speedMM, float & hx, float & hy) { // returns hand down; hx, hy in cells
		const float W = GW * MM, H = GH * MM; // mm
		static const float HUBS[3][2] = { { 0.30f, 0.42f }, { 0.67f, 0.59f }, { 0.49f, 0.73f } };
		left -= dt;
		if (left <= 0) {
			if (phase == "pause") {
				phase = "stroke"; left = 1.0f + rnd() * 1.2f;
				const int hub = (int)(rnd() * 3) % 3;
				x = HUBS[hub][0] * W + (rnd() - 0.5f) * 160; y = HUBS[hub][1] * H + (rnd() - 0.5f) * 120;
				a = rnd() * 6.2831853f; turn = (rnd() - 0.5f) * 3.0f;
			} else { phase = "pause"; left = 0.8f + rnd() * 1.6f; }
		}
		if (phase == "stroke") {
			a += turn * dt; x += std::cos(a) * speedMM * dt; y += std::sin(a) * speedMM * dt;
			if (x < 70 || x > W - 70 || y < 70 || y > H - 70) a += 3.14159265f * 0.7f;
			x = std::min(W - 40, std::max(40.0f, x)); y = std::min(H - 40, std::max(40.0f, y));
		}
		hx = x / MM; hy = y / MM;
		return phase == "stroke";
	}
};
// page handInput: carve along the path, pile part ahead (in the direction of motion)
static void handInput(World & w, bool down, float hx, float hy, float & px, float & py, bool & had, float dt, float carve)
{
	if (!down) { had = false; return; }
	const float fx = had ? px : hx, fy = had ? py : hy;
	const float dx = hx - fx, dy = hy - fy, dist = std::hypot(dx, dy) * MM;
	const int n = std::min(10, std::max(1, (int)std::ceil(dist / (BRUSH * 0.4f))));
	const float ux = dist > 0.5f ? dx * MM / dist : 0, uy = dist > 0.5f ? dy * MM / dist : 0;
	for (int k = 1; k <= n; k++) {
		const float x = fx + dx * k / n, y = fy + dy * k / n;
		const float dig = carve * dt / n;
		w.carve(x, y, dig, BRUSH);
		if (PILE > 0 && (ux != 0 || uy != 0)) w.carve(x + ux * BRUSH * 1.1f / MM, y + uy * BRUSH * 1.1f / MM, -dig * PILE * 1.25f, BRUSH * 0.894f);
	}
	px = hx; py = hy; had = true;
}

static std::string PRESETS;
static SM::RoleParams PRESET[3];
static std::string tagOf(const std::string & block, const std::string & name)
{
	std::string open = "<" + name + ">", close = "</" + name + ">";
	size_t a = block.find(open), b = block.find(close);
	if (a == std::string::npos || b == std::string::npos) return "";
	return block.substr(a + open.size(), b - a - open.size());
}
static bool readPreset(const std::string & path)
{
	std::ifstream f(path);
	if (!f) return false;
	std::stringstream ss; ss << f.rdbuf();
	std::string doc = ss.str();
	const char * roles[3] = { "ROLE_PIONEER", "ROLE_INTERMEDIATE", "ROLE_CLIMAX" };
	for (int r = 0; r < 3; r++) {
		std::string b = tagOf(doc, roles[r]);
		if (b.empty()) return false;
		auto rng = [&](const char * p, SM::Range & x) {
			x.min = (float)atof(tagOf(b, std::string(p) + "MIN").c_str()); x.max = (float)atof(tagOf(b, std::string(p) + "MAX").c_str());
			x.unit = tagOf(b, std::string(p) + "UNIT");
		};
		rng("MOISTURE", PRESET[r].moisture); rng("SLOPE", PRESET[r].slope); rng("SOILDEPTH", PRESET[r].soilDepth);
	}
	return true;
}
static void savePNG(const std::string & name, const std::vector<unsigned char> & img, int w, int h) { png::writeRGB(OUT + "/" + name, w, h, img); }
static double meanAbsDiff(const std::vector<unsigned char> & a, const std::vector<unsigned char> & b)
{
	double s = 0; for (size_t i = 0; i < a.size(); i++) s += std::abs((int)a[i] - (int)b[i]); return s / a.size();
}

// ------------------------------------------------------------ checks
static bool stable()
{
	bool ok = true;
	for (float sandVis : { 0.0f, 0.12f }) {
		SAND = sandVis;
		World w; w.pageSand(); w.noiseMM = 1.0f;
		MF f; f.clear();
		Look look; look.alloc();
		int touched = 0; double lit = 0, worst = 0, sum = 0; int nd = 0;
		std::vector<unsigned char> prev;
		for (int s = 0; s < 60 * 40; s++) {
			w.sample(false, 0, 0);
			f.step(w.mfInputs(nullptr));
			touched += f.touchedBlocks();
			look.step(f.getMycelium(), DT);
			if (s % 40 == 39 && s > 120) { // one frame per second, after the 2 s settle and a margin
				auto img = look.render(f.getMycelium());
				if (!prev.empty()) { const double d = meanAbsDiff(img, prev); sum += d; worst = std::max(worst, d); nd++; }
				prev = img;
			}
		}
		for (int i = 0; i < GW * GH; i++) lit += f.getMycelium().lit()[i];
		printf("stable (Sand visibility %.2f): +-1 mm per cell per frame on still sand, 60 s: touched block-steps %d, lit sum %.3g, "
			"segments %zu; rendered image (0..255) mean |frame-to-frame difference| %.4f (worst %.4f over %d pairs)\n",
			sandVis, touched, lit, f.getMycelium().segments().size(), nd ? sum / nd : 0.0, worst, nd);
		ok = ok && touched == 0 && lit == 0.0;
	}
	SAND = 0.0f;
	return ok;
}

static uint64_t fnv(const void * p, size_t n, uint64_t h = 1469598103934665603ull)
{
	const unsigned char * c = (const unsigned char *)p;
	for (size_t i = 0; i < n; i++) { h ^= c[i]; h *= 1099511628211ull; }
	return h;
}
static uint64_t hashModel(const SM & m)
{
	const size_t n = (size_t)GW * GH * sizeof(float);
	uint64_t h = fnv(m.cover(0), n); h = fnv(m.cover(1), n, h); h = fnv(m.cover(2), n, h);
	h = fnv(m.moisture(), n, h); return fnv(m.soil(), n, h);
}
static bool ident()
{
	std::string err;
	World wa, wb; wa.pageSand(); wb.pageSand();
	SM a, b; a.setParams(PRESET, err); b.setParams(PRESET, err);
	MF f; f.clear();
	Demo da, db; float pxa = 0, pya = 0, pxb = 0, pyb = 0; bool ha = false, hb = false;
	bool same = true;
	for (int s = 0; s < 2000; s++) {
		float ax, ay, bx, by;
		const bool downA = da.step(DT, HARNESS_SPEED, ax, ay), downB = db.step(DT, HARNESS_SPEED, bx, by);
		handInput(wa, downA, ax, ay, pxa, pya, ha, DT, HARNESS_CARVE); handInput(wb, downB, bx, by, pxb, pyb, hb, DT, HARNESS_CARVE);
		wa.sample(downA, ax, ay); wb.sample(downB, bx, by);
		SM::Inputs ia = wa.smInputs(), ib = wb.smInputs();
		a.step(ia); b.step(ib);
		f.step(wb.mfInputs(&b)); // module on run b only
		if ((s % 100 == 99 || s == 1999) && hashModel(a) != hashModel(b)) same = false;
	}
	const size_t n = (size_t)GW * GH * sizeof(float);
	const bool bytes = std::memcmp(a.cover(0), b.cover(0), n) == 0 && std::memcmp(a.cover(1), b.cover(1), n) == 0 &&
		std::memcmp(a.cover(2), b.cover(2), n) == 0 && std::memcmp(a.moisture(), b.moisture(), n) == 0 && std::memcmp(a.soil(), b.soil(), n) == 0;
	printf("ident: 2,000 steps with demo strokes; module lit cells %d, segments %zu; model hash alone %016llx, with module %016llx; "
		"every 100-step check identical: %s; final memcmp: %s\n", [&] { int c = 0; for (int i = 0; i < GW * GH; i++) c += f.getMycelium().lit()[i] > 0.5f; return c; }(),
		f.getMycelium().segments().size(), (unsigned long long)hashModel(a), (unsigned long long)hashModel(b), same ? "yes" : "NO", bytes ? "identical" : "DIFFERENT");
	return same && bytes;
}

static void stats(const char * name, std::vector<float> v)
{
	if (v.empty()) { printf("  %s: no samples\n", name); return; }
	std::sort(v.begin(), v.end());
	double s = 0; for (float x : v) s += x;
	printf("  %-22s mean %.2f ms, median %.2f, p95 %.2f, worst %.2f\n", name, s / v.size(), v[v.size() / 2], v[(size_t)(0.95 * (v.size() - 1))], v.back());
}
static void bench(int threads)
{
	const int saved = MF::THREADS; MF::THREADS = threads;
	World w; w.pageSand();
	MF f; f.clear();
	Demo d; float px = 0, py = 0; bool had = false;
	std::vector<float> part[6];
	// Stroke direction check: the stored direction against the hand's motion, under the hand
	// and on the trail 0.3 s behind it (where the streaks are seen once the hand has passed).
	std::deque<std::array<float, 5>> hist; // hx, hy, motion x, y, down
	double aU = 0, aT = 0; int nU = 0, nT = 0, unmarked = 0, good = 0;
	for (int s = 0; s < 120 * 40; s++) {
		float hx, hy;
		const bool down = d.step(DT, HARNESS_SPEED, hx, hy);
		const float mx = hist.empty() ? 0 : hx - hist.back()[0], my = hist.empty() ? 0 : hy - hist.back()[1];
		hist.push_back({ hx, hy, mx, my, down ? 1.0f : 0.0f });
		if (hist.size() > 13) hist.pop_front();
		auto align = [&](const std::array<float, 5> & h, double & acc, int & cnt) {
			const float ml = std::hypot(h[2], h[3]);
			const int cx = (int)h[0], cy = (int)h[1];
			if (h[4] < 0.5f || ml < 0.05f || ml > 5.0f || cx < 0 || cy < 0 || cx >= GW || cy >= GH) return;
			const MS & sim = f.getMycelium();
			const size_t c = (size_t)cy * GW + cx;
			if (sim.age()[c] > 0.6f) { unmarked++; return; } // not marked by this pass: keeps an older direction
			const float dx = sim.dirX()[c], dy = sim.dirY()[c];
			if (dx != 0 || dy != 0) { const float k = (dx * h[2] + dy * h[3]) / ml; acc += k; cnt++; if (&acc == &aT && k > 0.8f) good++; }
		};
		if (s > 40 * 10 && hist.size() == 13) { align(hist.back(), aU, nU); if (hist.back()[4] > 0.5f) align(hist.front(), aT, nT); }
		handInput(w, down, hx, hy, px, py, had, DT, HARNESS_CARVE);
		w.sample(down, hx, hy);
		f.step(w.mfInputs(nullptr));
		if (s > 40 * 10) {
			for (int k = 0; k < 5; k++) part[k].push_back(f.getPhaseMs(k));
			part[5].push_back(f.getLastStepMs());
		}
	}
	printf("bench (Mycelium, THREADS = %d, -O2, 120 s of demo strokes, last 110 s timed): %d growing threads, %zu segments at the end\n",
		threads, f.getMycelium().activeThreads(), f.getMycelium().segments().size());
	const char * nm[6] = { "touch", "marks + footprint", "mask", "liquid motion", "threads", "whole module step" };
	for (int k = 0; k < 6; k++) stats(nm[k], part[k]);
	printf("  stroke direction vs hand motion, cells marked by this pass (mean cos, 1 = along the sweep): under the hand %.2f (%d samples), on the trail 0.3 s behind %.2f (%d; %.0f %% above 0.8); %d samples not marked\n",
		nU ? aU / nU : 0.0, nU, nT ? aT / nT : 0.0, nT, nT ? 100.0 * good / nT : 0.0, unmarked);
	MF::THREADS = saved;
}

static void story()
{
	std::string err;
	World w; w.pageSand();
	SM m; m.setParams(PRESET, err);
	MF f; f.clear();
	Look look; look.alloc();
	Demo d; float px = 0, py = 0; bool had = false;
	const float WARM = 30.0f, STROKES = 60.0f, REST = 90.0f;
	const int steps = (int)((WARM + STROKES + REST) / DT);
	int frame = 0; bool blackBefore = true;
	std::vector<unsigned char> img;
	std::vector<float> dug(GW * GH, 0.0f), sand0 = w.sand;
	float firstLitDelay = -1; float tFirstDown = -1;
	double litAtRest = 0, litEnd = 0; size_t segAtRest = 0, segEnd = 0;
	for (int s = 0; s < steps; s++) {
		const float t = s * DT;
		float hx = 0, hy = 0;
		bool down = false;
		if (t >= WARM && t < WARM + STROKES) down = d.step(DT, HARNESS_SPEED, hx, hy);
		if (down && tFirstDown < 0) tFirstDown = t;
		handInput(w, down, hx, hy, px, py, had, DT, HARNESS_CARVE);
		w.sample(down, hx, hy);
		SM::Inputs si = w.smInputs();
		m.step(si);
		f.step(w.mfInputs(&m));
		look.step(f.getMycelium(), DT);
		if (firstLitDelay < 0 && tFirstDown >= 0) {
			const MS & sim = f.getMycelium();
			for (int i = 0; i < GW * GH; i++) if (sim.lit()[i] > 0.5f) { firstLitDelay = t - tFirstDown; break; }
		}
		if (s == (int)((WARM + STROKES + 1.0f) / DT)) { for (int i = 0; i < GW * GH; i++) litAtRest += f.getMycelium().lit()[i]; segAtRest = f.getMycelium().segments().size(); }
		const float u = t - WARM;
		const bool shoot = (u < 0 && s % (10 * 40) == 0) || (u >= 0 && u < STROKES + 30 && s % 20 == 0) || (u >= STROKES + 30 && s % 200 == 0);
		if (!shoot) continue;
		img = look.render(f.getMycelium());
		if (u < 0) for (unsigned char c : img) if (c) { blackBefore = false; break; }
		if (down) { // GIF annotation only: a grey ring where the simulated hand is
			const float r = BRUSH / MM * look.FP;
			for (int a = 0; a < 720; a++) {
				const int qx = (int)std::lround(hx * look.FP + r * std::cos(a * 0.008727f)), qy = (int)std::lround(hy * look.FP + r * std::sin(a * 0.008727f));
				if (qx < 0 || qy < 0 || qx >= look.FW || qy >= look.FH) continue;
				unsigned char * q = &img[((size_t)qy * look.FW + qx) * 3]; q[0] = q[1] = q[2] = 150;
			}
		}
		char name[64]; snprintf(name, sizeof name, "myc_%04d.png", frame++);
		savePNG(name, img, look.FW, look.FH);
		if (std::fabs(u - 45.0f) < 0.01f) savePNG("myc_still_45s.png", img, look.FW, look.FH);
	}
	for (int i = 0; i < GW * GH; i++) litEnd += f.getMycelium().lit()[i];
	segEnd = f.getMycelium().segments().size();
	savePNG("myc_still_end.png", img, look.FW, look.FH);
	const MS & sim = f.getMycelium();
	double warm = 0; int nl = 0;
	for (int i = 0; i < GW * GH; i++) if (sim.lit()[i] > 0.5f) { warm += 1.0 - std::exp(-sim.age()[i] / MATURE); nl++; }
	printf("story: %.0f s untouched, %.0f s of demo strokes (hand 34 mm, 100 mm/s, dig 25 mm/s, pile 0.6), %.0f s rest; frames black before touch: %s\n",
		WARM, STROKES, REST, blackBefore ? "yes" : "NO");
	printf("story: first light %.3f s after the first stroke began (one step = %.3f s)\n", firstLitDelay, DT);
	printf("story: stroke direction alignment is measured by the bench (cells marked by the pass)\n");
	printf("story: at the end, %d cells lit, mean warmth (0 cyan .. 1 amber) %.2f; threads: %zu segments, fusions %lld, stops on lit ground %lld\n",
		nl, nl ? warm / nl : 0.0, segEnd, sim.fusions(), sim.patchStops());
	printf("story: 1 s into the rest vs the end (89 s later): lit sum %.1f vs %.1f, segments %zu vs %zu (nothing fades)\n", litAtRest, litEnd, segAtRest, segEnd);
}

int main(int argc, char ** argv)
{
	if (argc < 2) { fprintf(stderr, "usage: %s <outdir> [repoRoot] [stable|ident|bench|story ...]\n", argv[0]); return 1; }
	OUT = argv[1];
	if (argc > 2) ROOT = argv[2];
	if (!readPreset(ROOT + "/bin/data/settings/ecologyParamsDesigner.xml")) { fprintf(stderr, "no preset\n"); return 1; }
	setvbuf(stdout, nullptr, _IOLBF, 0);
	makeNoise();
	MF::STYLE = MF::STYLE_MYCELIUM;
	if (const char * e = std::getenv("MYC_DIR_RADIUS")) MS::DIR_RADIUS_CELLS = std::atoi(e); // tuning runs only
	std::vector<std::string> which;
	for (int i = 3; i < argc; i++) which.push_back(argv[i]);
	auto want = [&](const char * k) { return which.empty() || std::find(which.begin(), which.end(), k) != which.end(); };
	bool ok = true;
	if (want("stable")) ok = stable() && ok;
	if (want("ident")) ok = ident() && ok;
	if (want("bench")) { bench(1); bench(4); }
	if (std::find(which.begin(), which.end(), "bench4") != which.end()) bench(4);
	if (want("story")) story();
	return ok ? 0 : 2;
}
